  }
  if (offset !== end) reject("zip");
  ranges.sort((a, b) => a[0] - b[0]);
  if (ranges.some((range, i) => i > 0 && range[0] < ranges[i - 1]![1])) reject("zip");
  return entries;
}

const unzip = promisify(inflateRaw);
function columnNumber(code: string): number {
