      /\((%|kWh|Wh|MWh|km|m|mm|cm|kg|g|s|ms|h|L|l|EUR|USD|vehicles|units|persons)\)/i.exec(header);
    if (match?.[1]) result.add(match[1]);
    if (/^(unit|units|unit of measure|einheit)$/i.test(header.trim())) {
      for (const row of rows)
