node --input-type=module - "$probe" <<'NODE'
import { cp, readFile, writeFile } from 'node:fs/promises';
import { join, resolve } from 'node:path';
const probe = process.argv[2];
for (const folder of ['main', 'preload', 'renderer']) {
  await cp(resolve('apps/desktop/out', folder), join(probe, folder), { recursive: true });
}
const main = join(probe, 'main/index.js');
let compiled = await readFile(main, 'utf8');
const replace = (from, to) => {
  if (!compiled.includes(from)) throw new Error('Expected compiled integration seam not found');
  compiled = compiled.replace(from, to);
};
replace('const smokeDir = parseSmokeArg(process.argv);', 'const smokeDir = parseSmokeArg(process.argv);\nif (smokeDir) electron.app.setPath("userData", minpath.join(smokeDir, "profile"));');
replace('  loadDevEnv();', '  // Native smoke probe never loads dotenv.');
replace('const devUrl = process.env.ELECTRON_RENDERER_URL;', 'const devUrl = undefined;');
replace('chooseImport: async () => {', 'fetchImpl: async () => { throw new Error("Offline native smoke prohibits network"); },\n    chooseImport: async () => {\n      if (smokeDir) return minpath.join(smokeDir, "original.synthetic.xlsx");');
replace('chooseExport: async (format, runId) => {', 'chooseExport: async (format, runId) => {\n      if (smokeDir) return minpath.join(smokeDir, `research-export.${format}`);');
await writeFile(main, compiled);
NODE
node_modules/.bin/electron "$probe/main/index.js" --smoke="$PWD/apps/desktop/out/smoke-probe"

